<template>
  <section class="stock-outlook" aria-label="One-year investment assessment">
    <template v-if="!outlook">
      <div class="outlook-empty"><div><h2>{{ run.one_year_status==='running'?'The one-year debate is underway':'One-year investment view' }}</h2><p>{{ run.one_year_status==='running'?'The supporting and opposing analysts are testing earnings growth, valuation and the strongest counterarguments.':'Add a supporting/opposing return debate and a transparent investment score to this saved research.' }}</p></div><button v-if="finished && run.one_year_status!=='running'" class="stock-primary" :disabled="busy" @click="$emit('generate')">{{ busy?'Starting…':'Add one-year assessment' }}</button></div>
      <p v-if="run.annual_error" class="stock-subtle">{{ run.annual_error }}</p>
    </template>
    <template v-else-if="outlook.status==='unavailable'"><div class="outlook-heading"><h2>One-year assessment unavailable</h2><span>Numbers and score withheld</span></div><p class="outlook-definition">{{ outlook.source_review_summary||outlook.unavailable_reasons?.join(' ')||'More source-grounded evidence or a validated assessment is required.' }}</p><details v-if="outlook.arguments&&Object.keys(outlook.arguments).length"><summary>Saved analyst arguments</summary><article v-for="(argument,side) in outlook.arguments" :key="side"><h3>{{ side==='for'?'Supporting case':'Opposing case' }}</h3><p><StockEvidenceText :text="argument.thesis" :sources="run.dossier?.sources||[]"/></p></article></details></template>
    <template v-else>
      <div class="outlook-heading"><h2>{{ provisional?'Provisional one-year scenarios':'One-year investment view' }}</h2><span>{{ outlook.evidence_strength || outlook.synthesis?.evidence_strength||'Not recorded' }} evidence · {{ outlook.target_date }}</span></div>
      <p v-if="outlook.source_review_status==='review_required'" class="source-review-note">{{ outlook.source_review_summary }} Earlier assumptions remain in the report for audit.</p>
      <StockForecastSummary v-if="compact" :run="run" @debate="$emit('open-debate')"/><div v-if="!compact" class="outlook-numbers"><div><span>{{ provisional?'Provisional investment score':'Investment quality' }}</span><strong>{{ outlook.investment_score ?? '—' }}<small>/ 10</small></strong><p>{{ outlook.investment_score===null?'More evidence is needed':'Weighted analyst judgement' }}</p></div><div><span>Expected 1-year price return</span><strong>{{ pct(outlook.expected_return) }}</strong><p>Central valuation scenario</p></div><div><span>Low scenario</span><strong class="low-return">{{ pct(outlook.low_return) }}</strong><p>Opposing assumptions</p></div><div><span>High scenario</span><strong class="high-return">{{ pct(outlook.high_return) }}</strong><p>Supporting assumptions</p></div><div><span>Evidence quality</span><strong class="evidence-quality">{{ outlook.evidence_strength || outlook.synthesis?.evidence_strength||'Not recorded' }}</strong><p>{{ outlook.target_date }}</p></div></div><div v-if="hasRange&&!compact" class="outlook-range" aria-label="One-year analyst scenario range"><div class="range-track"><i :style="{left:centralPosition+'%'}"/></div><div><span>Low {{ pct(outlook.low_return) }}</span><strong>Central {{ pct(outlook.expected_return) }}</strong><span>High {{ pct(outlook.high_return) }}</span></div></div>
      <p class="outlook-definition">{{ outlook.return_basis }} These are unvalidated analyst estimates; the range is not a statistical confidence interval.</p>
      <p v-if="!compact&&outlook.source_review_status!=='review_required'" class="outlook-summary"><StockEvidenceText :text="outlook.synthesis?.summary" :sources="run.dossier?.sources || []"/></p>
      <p v-if="compact&&Number.isFinite(outlook.investment_score)&&outlook.source_review_status!=='review_required'" class="compact-score">{{ provisional?'Provisional investment score':'Investment score' }}: <strong>{{ outlook.source_review_status==='review_required'?'Unavailable':outlook.investment_score ?? 'Unavailable' }}</strong><span v-if="outlook.investment_score!=null&&outlook.source_review_status!=='review_required'"> / 10 · weighted analyst judgement</span></p>
      <template v-else>
        <div class="annual-arguments"><article v-for="side in ['for','against']" :key="side" :class="side"><h3>{{ (outlook.source_review_status==='review_required'?'Earlier argument · ':'')+(side==='for'?'The case for':'The case against') }}</h3><p><StockEvidenceText :text="outlook.arguments?.[side]?.thesis" :sources="run.dossier?.sources || []"/></p><dl class="case-range"><div v-for="scenario in ['low','central','high']" :key="scenario"><dt>{{ scenario==='central'?'Central':scenario==='low'?'Low':'High' }}</dt><dd>{{ pct(outlook.cases?.[side]?.[scenario]?.return) }}</dd></div></dl><h4>Strongest opposing explanation</h4><p>{{ outlook.arguments?.[side]?.strongest_opposing_argument }}</p><div v-if="reply(side)" class="annual-rebuttal"><h4>Reply to the other analyst</h4><p>{{ reply(side).critique }}</p><h4>What this analyst concedes</h4><p>{{ reply(side).concession }}</p><h4>View after the debate</h4><p>{{ reply(side).revised_view }}</p></div></article></div>
        <details class="outlook-assumptions"><summary>How the return ranges are calculated</summary><p>{{ outlook.method }}</p><p v-if="outlook.central?.opportunity_ids?.length">Business drivers in the central scenario: {{ outlook.central.opportunity_ids.map(id=>opportunityName(run,id)).join(', ') }}. {{ outlook.central.transmission_reason }}</p><p>Reported annual EPS: {{ number(outlook.reported_annual_eps) }} {{ run.dossier?.metrics?.eps?.currency || '' }} per share · Reference price: {{ money(outlook.reference_price,run.dossier?.price?.currency||'USD') }}</p><p v-if="outlook.fx_reference">Valuation EPS: {{ number(outlook.valuation_annual_eps) }} {{ outlook.currency }} per share, converted at {{ number(outlook.fx_reference.rate) }} {{ outlook.fx_reference.to_currency || outlook.currency }} per {{ outlook.fx_reference.from_currency || run.dossier?.metrics?.eps?.currency }} as of {{ outlook.fx_reference.as_of }}. This fixed observed FX reference is not a forecast of future exchange rates.</p><div class="stock-table-wrap"><table class="stock-table"><thead><tr><th>Case</th><th>EPS growth assumption</th><th>Exit P/E assumption</th><th>Target price</th><th>Price return</th></tr></thead><tbody><template v-for="side in ['for','against']" :key="side"><tr v-for="scenario in ['low','central','high']" :key="scenario"><td>{{ side }} · {{ scenario }}</td><td>{{ pct(outlook.cases?.[side]?.[scenario]?.eps_growth) }}</td><td>{{ number(outlook.cases?.[side]?.[scenario]?.exit_pe) }}</td><td>{{ money(outlook.cases?.[side]?.[scenario]?.target_price,run.dossier?.price?.currency||'USD') }}</td><td>{{ pct(outlook.cases?.[side]?.[scenario]?.return) }}</td></tr></template></tbody></table></div><ul><li v-for="reason in outlook.unavailable_reasons" :key="reason">{{ reason }}</li></ul></details>
        <section v-if="Object.keys(scoredCriteria).length" class="score-breakdown"><h3>Why this investment score?</h3><p>Higher scores mean stronger investment attributes. Ratings below use the captured evidence.</p><article v-for="(grade,key) in scoredCriteria" :key="key"><div><strong>{{ outlook.score_labels?.[key]||key }}</strong><span>{{ Math.round(outlook.score_weights?.[key]*100) }}% weight</span><b>{{ grade.score }}<small v-if="grade.score!==null"> / 10</small></b></div><p><StockEvidenceText :text="grade.reason" :sources="run.dossier?.sources || []"/></p></article></section>
        <section v-if="outlook.synthesis?.change_conditions?.length" class="outlook-changes"><h3>What would change this view?</h3><ul><li v-for="text in outlook.synthesis?.change_conditions||[]" :key="text">{{ text }}</li></ul></section>
      </template>
    </template>
  </section>
</template>
<script setup>
import { computed } from 'vue'
import StockForecastSummary from './StockForecastSummary.vue'
import StockEvidenceText from './StockEvidenceText.vue'
import {stockAssessmentProvisional} from '../utils/stockForecast.mjs'
import {opportunityName} from '../utils/stockFramework.mjs'
import { money,number } from '../api/stocklab'
const props=defineProps({run:{type:Object,required:true},compact:Boolean,busy:Boolean})
defineEmits(['generate','open-debate'])
const outlook=computed(()=>props.run.one_year)
const scoredCriteria=computed(()=>Object.fromEntries(Object.entries(outlook.value?.scorecard||{}).filter(([,grade])=>Number.isFinite(grade?.score))))
const provisional=computed(()=>stockAssessmentProvisional(props.run))
const hasRange=computed(()=>[outlook.value?.low_return,outlook.value?.high_return,outlook.value?.expected_return].every(Number.isFinite)&&outlook.value.high_return>outlook.value.low_return)
const centralPosition=computed(()=>hasRange.value?Math.max(0,Math.min(100,(outlook.value.expected_return-outlook.value.low_return)/(outlook.value.high_return-outlook.value.low_return)*100)):50)
const finished=computed(()=>['complete','complete_with_gaps'].includes(props.run.status))
const pct=value=>Number.isFinite(value)?`${value>=0?'+':''}${(value*100).toFixed(1)}%`:'Unavailable'
const reply=side=>outlook.value?.exchange?.replies?.find(item=>item.actor_id==='annual_'+side)
</script>
<style scoped>
.compact-score{font-size:12px;color:#60748b;margin:9px 0}.compact-score strong{font-size:18px;color:#283849;font-weight:500}

