@media(max-width:850px){.outlook-numbers{grid-template-columns:1fr;gap:17px;padding:20px 0}.outlook-numbers>div{display:grid;grid-template-columns:1fr auto;align-items:center;column-gap:15px}.outlook-numbers strong,.outlook-numbers .range-number{font-size:28px;margin:0}.outlook-numbers>div>p{grid-column:1/-1;margin:3px 0 0}.outlook-heading{align-items:start;flex-direction:column;gap:6px}.annual-arguments{grid-template-columns:1fr;gap:24px}.outlook-empty{flex-direction:column;align-items:start}.outlook-empty button{width:100%}.outlook-numbers .range-number small{font-size:12px}}
.outlook-numbers{grid-template-columns:1.1fr 1.1fr 1fr 1fr .85fr;gap:0}.outlook-numbers>div{padding:0 15px;border-right:1px solid #edf0f4}.outlook-numbers>div:first-child{padding-left:0}.outlook-numbers>div:last-child{border-right:0}.outlook-numbers .evidence-quality{font-size:19px;line-height:1.7;text-transform:capitalize;letter-spacing:-.4px}.outlook-numbers .low-return{color:#a06659}.outlook-numbers .high-return{color:#527c67}.outlook-range{margin:20px 0}.range-track{height:4px;background:linear-gradient(to right,#e8d5cb,#dde5e2,#bcd5c7);border-radius:5px;position:relative}.range-track i{position:absolute;top:-4px;height:12px;width:2px;background:#405b4d}.outlook-range>div:last-child{display:flex;justify-content:space-between;gap:12px;margin-top:12px;font-size:10px;color:#697589}.outlook-range strong{font-weight:500}.outlook-definition{max-width:950px}@media(max-width:1200px){.outlook-numbers>div{padding:0 10px}.outlook-numbers strong{font-size:27px}.outlook-numbers>div>span{font-size:11px}}@media(max-width:850px){.outlook-numbers{grid-template-columns:1fr 1fr;gap:0;padding:0}.outlook-numbers>div{padding:16px 14px!important;border-bottom:1px solid #edf0f4;display:block}.outlook-numbers>div:nth-child(2n){border-right:0}.outlook-numbers>div:last-child{grid-column:1/-1;border-bottom:0}.outlook-numbers strong{margin:7px 0 0}.outlook-range>div:last-child{font-size:9px}.outlook-numbers .evidence-quality{font-size:18px}}
</style>
